 endforeach;?></div></section><section class="provider-results"><header><div><span>APPROVED LOCAL PROVIDERS</span><h2><?=number_format(count($providers))?> providers found</h2></div><a href="/service-provider-register.php">Become a Service Provider →</a></header><div class="provider-list"><?php if(!$providers):?><div class="empty"><b>No approved providers match these filters yet.</b><p>Post a service request so providers in that category can respond when available.</p><a class="btn" href="/request-service.php">Post a Request</a></div><?php else:foreach($providers as $p)sk1380_provider_card($p);endif;?></div></section><?php sk1380_end();